<script setup lang="ts">
import type { DocumentRecord, Station, Page, CommandResult } from '~/utils/types'
type WorkItem = DocumentRecord & { action?: 'CONFIRM_RECEIPT'|'READY'|'CONFIRM_RETURN'|null; action_route_step_id?: string }
const api=useApi();const {actor,courier,unitIds}=useSession();const station=ref('');const stations=ref<Station[]>([]);const docs=ref<WorkItem[]>([]);const cursor=ref<string|null>();const loading=ref(false);const saving=ref('');const error=ref<unknown>();const message=ref('');const mode=ref<'unit'|'courier'>(unitIds.value.length?'unit':'courier');const operation=ref<CommandResult>();let generation=0
const availableStations=computed(()=>stations.value.filter(s=>actor.value?.station_ids.includes(s.id)&&(mode.value==='courier'||unitIds.value.includes(s.unit_id))))
async function load(more=false){if(!station.value)return;const run=++generation;loading.value=true;error.value=undefined;try{const page=await api.get<Page<WorkItem>>(`/stations/${encodeURIComponent(station.value)}/${mode.value==='unit'?'unit-worklist':'worklist'}?limit=50${more&&cursor.value?`&cursor=${encodeURIComponent(cursor.value)}`:''}`);if(run!==generation)return;docs.value=more?[...docs.value,...page.items]:page.items;cursor.value=page.next_cursor}catch(e){if(run===generation)error.value=e}finally{if(run===generation)loading.value=false}}
async function changeMode(value:'unit'|'courier'){mode.value=value;docs.value=[];cursor.value=null;station.value=availableStations.value[0]?.id||'';await load()}
async function reserve(doc:DocumentRecord){saving.value=doc.id;error.value=undefined;message.value='';try{await api.command('/courier/reservations',{station_id:station.value,items:[{document_id:doc.id,route_step_id:doc.current_route_step_id,expected_version:doc.version}]});message.value='จองแล้ว ไปการจองของฉันเพื่อตรวจหนังสือจริงและถ่ายรูปก่อน Check รับ';await load()}catch(e){error.value=e}finally{saving.value=''}}
async function act(doc:WorkItem){if(!doc.action||!doc.action_route_step_id)return;saving.value=doc.id;error.value=undefined;message.value='';try{const step={route_step_id:doc.action_route_step_id,expected_version:doc.version};operation.value=doc.action==='CONFIRM_RECEIPT'?await api.command<CommandResult>(`/stations/${station.value}/confirm-receipt`,{station_id:station.value,items:[{document_id:doc.id,...step}]}):await api.command<CommandResult>(`/documents/${doc.id}/${doc.action==='READY'?'ready':'confirm-return'}`,step);message.value='บันทึกคำสั่งแล้ว รอ workflow ประสานก่อนทำขั้นตอนถัดไป';await load()}catch(e){error.value=e}finally{saving.value=''}}
const actionLabel=(action:WorkItem['action'])=>action==='READY'?'พร้อมจัดส่ง':action==='CONFIRM_RETURN'?'ยืนยันรับคืนต้นทาง':'ยืนยันรับหนังสือ'
onMounted(async()=>{try{stations.value=(await api.get<Page<Station>>('/stations')).items;station.value=availableStations.value[0]?.id||'';await load()}catch(e){error.value=e}})
onBeforeUnmount(()=>generation++)
</script>
<template><div class="page-head"><div><h1>งานประจำ Station</h1><p>หน่วยงานยืนยันรับและพร้อมจัดส่งแยกจากรายงานของ Courier หนังสือใหม่เข้าคิวรับเมื่อหน่วยงานต้นทางพร้อมแล้ว</p></div><NuxtLink v-if="courier" class="button" to="/reservations">การจองของฉัน</NuxtLink></div><Feedback :error="error" :message="message" /><div class="view-tabs" role="group" aria-label="เลือกประเภทงาน"><button v-if="unitIds.length" type="button" data-testid="station-unit-tab" class="button" :aria-pressed="mode==='unit'" @click="changeMode('unit')">งานหน่วยงาน</button><button v-if="courier" type="button" data-testid="station-courier-tab" class="button" :aria-pressed="mode==='courier'" @click="changeMode('courier')">คิวรับของ Courier</button></div><OperationStatus v-if="operation" :operation-id="operation.operation_id" :sync-status="operation.process_sync_status" @applied="operation=undefined;load()" /><section class="panel"><form class="actions" @submit.prevent="load()"><div class="field"><label for="work-station">Station ที่มีสิทธิ์</label><select id="work-station" v-model="station" data-testid="station-select" required @change="docs=[];cursor=null;load()"><option disabled value="">เลือก Station</option><option v-for="s in availableStations" :key="s.id" :value="s.id">{{s.name}}</option></select></div><button class="button" :disabled="loading||!station">โหลดล่าสุด</button></form><UProgress v-if="loading" /><div v-if="!docs.length&&!loading" class="empty"><h2>{{availableStations.length?'ไม่มีรายการที่พร้อมดำเนินการ':'ไม่มีสิทธิ์ Station สำหรับงานนี้'}}</h2><p>{{mode==='courier'?'คิวนี้แสดงเฉพาะหนังสือที่พร้อมรับและ workflow ประสานแล้ว':'เลือก Station ที่สังกัดหน่วยงานและได้รับสิทธิ์ เพื่อยืนยันรับหรือพร้อมจัดส่ง'}}</p></div><div class="table-wrap"><table v-if="docs.length"><thead><tr><th>หนังสือ</th><th>สถานะงาน</th><th>Workflow</th><th>ดำเนินการ</th></tr></thead><tbody><tr v-for="doc in docs" :key="doc.id"><td><NuxtLink v-if="unitIds.includes(doc.origin_unit_id)" :to="`/documents/${doc.id}`">{{doc.title||doc.document_number||`หนังสือ #${doc.id.slice(-8)}`}}</NuxtLink><span v-else class="row-title">หนังสือ #{{doc.id.slice(-8)}}</span><p class="hint">{{doc.tracking_mode==='MODEL_B'?'Model B':'Model A · ดูข้อมูลเท่านั้น'}}</p></td><td><StatusTag :value="doc.business_state" /></td><td><StatusTag :value="doc.process_sync_status" /></td><td><template v-if="doc.tracking_mode==='MODEL_B'"><button v-if="mode==='courier'" :data-testid="`reserve-${doc.id}`" class="button" :disabled="!!saving||doc.process_sync_status!=='APPLIED'" @click="reserve(doc)">{{saving===doc.id?'กำลังจอง…':'จองหนังสือนี้'}}</button><button v-else-if="doc.action" :data-testid="`${doc.action==='READY'?'ready':doc.action==='CONFIRM_RETURN'?'return':'receipt'}-${doc.id}`" class="button primary" :disabled="!!saving||doc.process_sync_status!=='APPLIED'" @click="act(doc)">{{saving===doc.id?'กำลังบันทึก…':actionLabel(doc.action)}}</button><p v-else class="hint">{{doc.process_sync_status!=='APPLIED'?'รอ workflow ประสาน':'ยังไม่มีคำสั่งสำหรับสถานะนี้'}}</p></template><p v-else class="hint">คำสั่ง Model A จะเปิดใน P4</p></td></tr></tbody></table></div><button v-if="cursor" class="button actions" :disabled="loading" @click="load(true)">โหลดงานเพิ่มเติม</button></section></template>
